    --surface2:    #1c2030;
    --border:      #272d3d;
    --border2:     #323a52;
    --text:        #e2e6f0;
    --muted:       #7b8299;
    --accent:      #4f8ef7;
    --accent-dim:  #1e3a6e;
    --green:       #22c55e;
    --green-dim:   #14532d;
    --amber:       #f59e0b;
    --amber-dim:   #451a03;
    --red:         #ef4444;
